423	static int ws_recv_frame(asr_tls_ctx_t* ctx,
424	    unsigned char* buf, size_t cap,
425	    size_t* out_len, int* out_opcode)
426	{
427	    unsigned char hdr[2];
428	    int ret = tls_read_all(ctx, hdr, 2);
429	
430	    if (ret != 0) {
431	        return ret;
432	    }
433	
434	    *out_opcode = hdr[0] & 0x0F;
435	    int masked = (hdr[1] & WS_MASK_BIT) != 0;
436	    size_t plen = hdr[1] & 0x7F;
437	
438	    if (plen == 126) {
439	        unsigned char ext[2];
440	
441	        ret = tls_read_all(ctx, ext, 2);
442	        if (ret != 0) {
443	            return ret;
444	        }
445	        plen = ((size_t)ext[0] << 8) | ext[1];
446	    } else if (plen == 127) {
447	        unsigned char ext[8];
448	
449	        ret = tls_read_all(ctx, ext, 8);
450	        if (ret != 0) {
451	            return ret;
452	        }
453	        plen = ((size_t)ext[4] << 24) | ((size_t)ext[5] << 16)
454	            | ((size_t)ext[6] << 8) | ext[7];
455	    }
456	
457	    unsigned char mask[WS_MASK_KEY_LEN];
458	
459	    if (masked) {
460	        ret = tls_read_all(ctx, mask, WS_MASK_KEY_LEN);
461	        if (ret != 0) {
462	            return ret;
463	        }
464	    }
465	
466	    if (plen > cap) {
467	        syslog(LOG_ERR, "[%s] WS frame too large: %zu > %zu\n",
468	            TAG, plen, cap);
469	        return -EOVERFLOW;
470	    }
471	
472	    if (plen > 0) {
473	        ret = tls_read_all(ctx, buf, plen);
474	        if (ret != 0) {
475	            return ret;
476	        }
477	        if (masked) {
478	            for (size_t i = 0; i < plen; i++) {
479	                buf[i] ^= mask[i % 4];
480	            }
481	        }
482	    }
483	
484	    *out_len = plen;
485	    return 0;
486	}
