506	    frame[2] = serialization;
507	    frame[3] = 0x00;
508	    frame[4] = (unsigned char)((plen >> 24) & 0xFF);
509	    frame[5] = (unsigned char)((plen >> 16) & 0xFF);
510	    frame[6] = (unsigned char)((plen >> 8) & 0xFF);
511	    frame[7] = (unsigned char)(plen & 0xFF);
512	
513	    if (plen > 0) {
514	        memcpy(frame + VOLC_HDR_SIZE, payload, plen);
