    42	
    43	audio_playback_t* audio_playback_open(const char* dev_path,
    44	    unsigned int sample_rate, unsigned int channels,
    45	    unsigned int bits_per_sample)
    46	{
    47	    (void)dev_path;
    48	
    49	    if (s_active_player) {
    50	        syslog(LOG_WARNING, "[%s] force closing stale player\n", TAG);
    51	        media_player_stop(s_active_player);
    52	        media_player_close(s_active_player, 0);
    53	        s_active_player = NULL;
    54	        usleep(100000);
    55	    }
    56	
    57	    void* player = media_player_open(MEDIA_STREAM_MUSIC);
    58	    if (!player) {
    59	        syslog(LOG_ERR, "[%s] media_player_open failed\n", TAG);
    60	        return NULL;
    61	    }
    62	
    63	    char opts[PB_OPTIONS_LEN];
    64	    snprintf(opts, sizeof(opts),
    65	        "format=s%ule:sample_rate=%u:ch_layout=%s",
    66	        bits_per_sample, sample_rate,
    67	        (channels == 1) ? "mono" : "stereo");
    68	
    69	    int ret = media_player_prepare(player, NULL, opts);
    70	    if (ret < 0) {
    71	        syslog(LOG_ERR, "[%s] prepare failed: %d\n", TAG, ret);
    72	        media_player_close(player, 0);
    73	        return NULL;
    74	    }
    75	
    76	    ret = media_player_start(player);
    77	    if (ret < 0) {
    78	        syslog(LOG_ERR, "[%s] start failed: %d\n", TAG, ret);
    79	        media_player_close(player, 0);
    80	        return NULL;
    81	    }
    82	
    83	    audio_playback_t* pb = calloc(1, sizeof(*pb));
    84	    if (!pb) {
    85	        media_player_close(player, 0);
    86	        return NULL;
    87	    }
    88	
    89	    pb->player = player;
    90	    pb->bytes_per_frame = (bits_per_sample / 8) * channels;
    91	    s_active_player = player;
    92	
    93	    syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit)\n",
    94	        TAG, sample_rate, channels, bits_per_sample);
    95	    return pb;
    96	}
    97	
    98	int audio_playback_write(audio_playback_t* pb, const void* buf, size_t len)
    99	{
   100	    if (!pb || !pb->player || !buf || len == 0) {
   101	        return -EINVAL;
   102	    }
   103	
   104	    if (pb->stopped) {
   105	        return -ECANCELED;
   106	    }
   107	
   108	    ssize_t n = media_player_write_data(pb->player, buf, len);
   109	    if (n > 0) {
   110	        pb->total_written += (size_t)n;
   111	    }
   112	
   113	    return (int)n;
   114	}
   115	
   116	void audio_playback_stop(audio_playback_t* pb)
   117	{
   118	    if (pb) {
   119	        pb->stopped = 1;
   120	        if (pb->player) {
   121	            media_player_stop(pb->player);
   122	        }
   123	    }
   124	}
   125	
   126	void audio_playback_close(audio_playback_t* pb)
   127	{
   128	    if (!pb) {
   129	        return;
   130	    }
   131	
   132	    if (pb->player) {
   133	        syslog(LOG_INFO, "[%s] closing (%zu bytes written)\n",
   134	            TAG, pb->total_written);
   135	        media_player_stop(pb->player);
   136	        usleep(50 * 1000);
   137	        media_player_close(pb->player, 0);
   138	        s_active_player = NULL;
   139	    }
   140	
   141	    free(pb);
   142	}

