    90	static int volc_tts_synthesize(const char* text,
    91	    unsigned char* pcm_out,
    92	    size_t pcm_cap,
    93	    size_t* pcm_len)
    94	{
    95	    if (!text || !pcm_out || !pcm_len) {
    96	        return -EINVAL;
    97	    }
    98	
    99	    /* Reload credentials in case they changed at runtime */
   100	    volc_tts_init();
   101	
   102	    if (s_api_key[0] == '\0') {
   103	        syslog(LOG_ERR, "[%s] API key not configured\n", TAG);
   104	        return -ENOENT;
   105	    }
   106	
   107	    *pcm_len = 0;
   108	
   109	    char* body = build_tts_request(text, s_speaker);
   110	
   111	    if (!body) {
   112	        syslog(LOG_ERR, "[%s] Failed to build TTS request\n", TAG);
   113	        return -ENOMEM;
   114	    }
   115	
   116	    vela_header_t hdrs[] = {
   117	        { "x-api-key", s_api_key },
   118	        { "X-Api-Resource-Id", AGENT_DOUBAO_TTS_RESOURCE },
   119	        { "Connection", "close" },
   120	        { NULL, NULL }
   121	    };
   122	
   123	    char* resp = calloc(1, AGENT_VOICE_RESP_BUF_SIZE);
   124	
   125	    if (!resp) {
   126	        free(body);
   127	        return -ENOMEM;
   128	    }
   129	
   130	    syslog(LOG_INFO, "[%s] TTS V3 request: text=%zu bytes\n",
   131	        TAG, strlen(text));
   132	
   133	    size_t body_len;
   134	    int status = vela_https_request(
   135	        AGENT_DOUBAO_TTS_HOST, AGENT_DOUBAO_TTS_PORT,
   136	        "POST", AGENT_DOUBAO_TTS_V3_PATH, hdrs,
   137	        body, strlen(body),
   138	        resp, AGENT_VOICE_RESP_BUF_SIZE, &body_len);
   139	
   140	    free(body);
   141	    body = NULL;
   142	
   143	    if (status != 200) {
   144	        syslog(LOG_ERR, "[%s] TTS HTTP %d: %.256s\n",
   145	            TAG, status, resp);
   146	        free(resp);
   147	        return -EIO;
   148	    }
   149	
   150	    if (body_len == 0) {
   151	        syslog(LOG_ERR, "[%s] TTS: empty response body\n", TAG);
   152	        free(resp);
   153	        return -EPROTO;
   154	    }
   155	
   156	    size_t total_pcm = 0;
   157	    int chunks = 0;
   158	    char* line = resp;
   159	
   160	    while (line && *line) {
   161	        while (*line == '\n' || *line == '\r' || *line == ' ') {
   162	            line++;
   163	        }
   164	
   165	        if (*line == '\0') {
   166	            break;
   167	        }
   168	
   169	        char* eol = strchr(line, '\n');
   170	
   171	        if (eol) {
   172	            *eol = '\0';
   173	        }
   174	
   175	        cJSON* obj = cJSON_Parse(line);
   176	
   177	        if (!obj) {
   178	            /* Truncated JSON at buffer boundary — skip silently
   179	             * if we already decoded some audio data. */
   180	            if (total_pcm > 0) {
   181	                syslog(LOG_WARNING,
   182	                    "[%s] TTS: truncated chunk %d (buffer full), "
   183	                    "using %zu bytes decoded so far\n",
   184	                    TAG, chunks, total_pcm);
   185	                break;
   186	            }
   187	            syslog(LOG_ERR, "[%s] TTS: bad JSON chunk %d: %.80s\n",
   188	                TAG, chunks, line);
   189	            break;
   190	        }
   191	
   192	        cJSON* code_j = cJSON_GetObjectItem(obj, "code");
   193	        int code_val = code_j ? (int)code_j->valuedouble : -1;
   194	
   195	        if (!code_j || !cJSON_IsNumber(code_j)
   196	            || (code_val != 0 && code_val != 20000000)) {
   197	            cJSON* msg_j = cJSON_GetObjectItem(obj, "message");
   198	
   199	            syslog(LOG_ERR, "[%s] TTS error %d: %.80s\n",
   200	                TAG, code_val,
   201	                (msg_j && msg_j->valuestring)
   202	                    ? msg_j->valuestring
   203	                    : line);
   204	            cJSON_Delete(obj);
   205	            free(resp);
   206	            return -EIO;
   207	        }
   208	
   209	        cJSON* data_j = cJSON_GetObjectItem(obj, "data");
   210	
   211	        if (data_j && cJSON_IsString(data_j)
   212	            && data_j->valuestring[0]) {
   213	            const char* b64 = data_j->valuestring;
   214	            size_t b64_len = strlen(b64);
   215	            size_t decoded_len;
   216	
   217	            if (total_pcm + (b64_len * 3 / 4) > pcm_cap) {
   218	                syslog(LOG_ERR,
   219	                    "[%s] TTS: PCM buffer full at chunk %d\n",
   220	                    TAG, chunks);
   221	                cJSON_Delete(obj);
   222	                break;
   223	            }
   224	
   225	            mbedtls_base64_decode(
   226	                pcm_out + total_pcm, pcm_cap - total_pcm,
   227	                &decoded_len,
   228	                (const unsigned char*)b64, b64_len);
   229	            total_pcm += decoded_len;
   230	            chunks++;
   231	        }
   232	
   233	        cJSON_Delete(obj);
   234	        line = eol ? eol + 1 : NULL;
   235	    }
   236	
   237	    free(resp);
   238	    resp = NULL;
   239	
   240	    if (total_pcm == 0) {
   241	        syslog(LOG_ERR, "[%s] TTS: no PCM data decoded\n", TAG);
   242	        return -EPROTO;
   243	    }
   244	
   245	    *pcm_len = total_pcm;
   246	
   247	    syslog(LOG_INFO,
   248	        "[%s] TTS: synthesized %zu PCM bytes (%d chunks)\n",
   249	        TAG, *pcm_len, chunks);
   250	    return 0;
   251	}
