   253	/* ── Streaming TTS (callback per chunk) ──────────────────────── */
   254	
   255	/* Streaming path uses smaller b64 decode buffer than batch.
   256	 * The resp buffer stays at 128KB to support up to ~4s of TTS
   257	 * audio (typical LLM reply length).  For >4s audio, true
   258	 * chunked HTTP reception would be needed (future work).
   259	 * Net saving vs batch: 80KB (b64 96KB→16KB). */
   260	#define VOLC_TTS_STREAM_RESP_SIZE (512 * 1024)
   261	#define VOLC_TTS_STREAM_B64_SIZE (16 * 1024)
