#define BEEP_SINE_TABLE 256

static const int16_t beep_sine[BEEP_SINE_TABLE] = { ... };

/* Generate a short sine-wave beep and play it through the playback
 * device. freq_hz selects the tone, duration_ms its length. Used as an
 * attention cue before a TTS reply so a notification is audible even
 * when the speaker volume is low. */
int voice_channel_beep(unsigned int freq_hz, unsigned int duration_ms)
{
    /* Clamp to sane ranges */
    if (freq_hz < 100 || freq_hz > 8000) freq_hz = 1000;
    if (duration_ms == 0 || duration_ms > 5000) duration_ms = 200;

    const unsigned int rate = AGENT_VOICE_SAMPLE_RATE;
    const unsigned int n = (unsigned int)((uint64_t)rate * duration_ms / 1000);

    int16_t* buf = malloc(n * sizeof(int16_t));
    if (!buf) return -ENOMEM;

    /* Phase increment in table units (fixed-point 16.16) */
    uint32_t phase = 0;
    uint32_t inc = (uint32_t)((uint64_t)freq_hz * BEEP_SINE_TABLE * 65536 / rate);

    /* ~15ms fade-in / fade-out to avoid clicks */
    unsigned int fade = rate * 15 / 1000;
    if (fade == 0) fade = 1;

    for (unsigned int i = 0; i < n; i++) {
        int32_t s = beep_sine[(phase >> 16) & (BEEP_SINE_TABLE - 1)];

        /* linear envelope */
        unsigned int a = 1;
        if (i < fade) a = i * 256 / fade;
        else if (i >= n - fade) a = (n - 1 - i) * 256 / fade;

        buf[i] = (int16_t)(s * (int32_t)a / 256);
        phase += inc;
    }

    audio_playback_t* pb = audio_playback_open(
        AGENT_AUDIO_PLAYBACK_DEV, rate,
        AGENT_VOICE_CHANNELS, AGENT_VOICE_BITS);
    if (!pb) {
        free(buf);
        return -EIO;
    }

    int ret = audio_playback_write(pb, buf, n * sizeof(int16_t));
    if (ret < 0) {
        syslog(LOG_WARNING, "[%s] beep write failed: %d\n", TAG, ret);
    }
    audio_playback_close(pb);
    free(buf);

    return (ret < 0) ? ret : 0;
}
