91	/* Fill an S16_LE buffer with a bounded sine wave at g_freq_hz.  phase is
92	 * carried across buffers so sample-boundary discontinuities do not create
93	 * audible clicks.
94	 */
95	
96	/* Precomputed sine LUT: computing sin() per-sample inside the DEQUEUE
97	 * refill path made the producer fall behind the DMA drain (underruns).
98	 * Index the LUT by phase instead; no per-frame transcendental call.
99	 */
100	
101	#define SINE_LUT_SIZE 256
102	#define SINE_AMP      4000    /* peak sample; ~12% FS. */
103	static int16_t g_sine_lut[SINE_LUT_SIZE];
104	static bool    g_sine_lut_ready = false;
105	
106	static void sine_lut_init(void)
107	{
108	  int i;
109	
110	  if (g_sine_lut_ready)
111	    {
112	      return;
113	    }
114	
115	  for (i = 0; i < SINE_LUT_SIZE; i++)
116	    {
117	      g_sine_lut[i] =
118	        (int16_t)(SINE_AMP * sin(2.0 * M_PI * (double)i / SINE_LUT_SIZE));
119	    }
120	
121	  g_sine_lut_ready = true;
122	}
123	
124	static void fill_sine(FAR int16_t *dst, size_t nsamples,
125	                      FAR double *phase)
126	{
127	  const double step  = 2.0 * M_PI * g_freq_hz / (double)g_sample_rate;
128	  const double scale = (double)SINE_LUT_SIZE / (2.0 * M_PI);
129	  size_t i;
130	
131	  sine_lut_init();
132	
133	  for (i = 0; i < nsamples; i += g_channels)
134	    {
135	      uint32_t idx = (uint32_t)(*phase * scale) & (SINE_LUT_SIZE - 1);
136	      int16_t  s   = g_sine_lut[idx];
137	      int c;
138	
139	      for (c = 0; c < g_channels; c++)
140	        {
141	          dst[i + c] = s;
142	        }
143	
144	      *phase += step;
145	      if (*phase >= 2.0 * M_PI)
146	        {
147	          *phase -= 2.0 * M_PI;
148	        }
149	    }
150	}
