219	      return EXIT_FAILURE;
220	    }
221	  printf("[bk-N] start ok, capturing ~%lu ms\n",
222	         (unsigned long)g_duration_ms); fflush(stdout);
223	
224	  while (samples < target)
225	    {
226	      ssize_t n = read(fd, buf, sizeof(buf));
227	      if (n > 0)
228	        {
229	          int nsamp = (int)(n / (ssize_t)sizeof(int16_t));
230	          int i;
231	
232	          for (i = 0; i < nsamp; i++)
233	            {
234	              int16_t s = buf[i];
235	              if (s < min) min = s;
236	              if (s > max) max = s;
237	              dc += s;
238	            }
239	          samples += (uint32_t)nsamp;
240	          starved = 0;
241	        }
242	      else if (n < 0)
243	        {
244	          if (errno == EAGAIN)
245	            {
246	              if (++starved > 2000)
247	                {
248	                  fprintf(stderr, "[bk-N] FIFO starved >2s, bailing\n");
249	                  break;
250	                }
251	              usleep(1000);
252	              continue;
253	            }
254	
255	          fprintf(stderr, "[bk-N] read failed: %d\n", errno);
256	          break;
257	        }
258	      else
259	        {
260	          /* EOF should not happen on a capture device. */
261	          break;
262	        }
263	    }
264	
265	  (void)ioctl(fd, AUDIOIOC_STOP, 0);
266	  close(fd);
267	
268	  printf("[bk-N] samples=%lu min=%ld max=%ld dc=%ld pp=%ld %s\n",
269	         (unsigned long)samples, (long)min, (long)max,
270	         (long)(samples ? dc / (int32_t)samples : 0),
271	         (long)(samples ? (max - min) : 0),
272	         (samples && (max - min) >= 200) ? "LIVE" : "FLAT?");
273	
274	  return EXIT_SUCCESS;
275	}
