725	      dac_cfg.channel   = BK7258_DAC_CHL_LR;
726	      dac_cfg.work_mode = BK7258_DAC_WORK_DIFFEN;
727	      dac_cfg.gain      = 0;
728	      dac_cfg.use_apll  = false;
729	
730	      ret = bk7258_aud_subsystem_init();
