```c
static struct ap_buffer_s* nuttx_get_free_buffer(audio_playback_t* pb)
{
    struct audio_msg_s msg;
    struct timespec to;
    unsigned int prio;
    ssize_t n;

    while (pb->free_count == 0) {
        if (pb->stopped) {
            return NULL;
        }

        clock_gettime(CLOCK_REALTIME, &to);
        to.tv_sec += 1;
        n = mq_timedreceive(pb->mq, (char*)&msg, sizeof(msg), &prio, &to);
        if (n < 0) {
            if (errno == ETIMEDOUT) {
                continue;  /* re-check stopped */
            }
            syslog(LOG_ERR, "[%s] mq_receive failed: %d\n", TAG, errno);
            return NULL;
        }

        if (msg.msg_id == AUDIO_MSG_DEQUEUE && msg.u.ptr) {
            pb->freeq[pb->free_count++] = (struct ap_buffer_s*)msg.u.ptr;
        } else if (msg.msg_id == AUDIO_MSG_IOERR ||
                   msg.msg_id == AUDIO_MSG_COMPLETE) {
            syslog(LOG_ERR, "[%s] playback msg %u\n", TAG, msg.msg_id);
            return NULL;
        }
        /* AUDIO_MSG_UNDERRUN etc.: ignore, keep waiting for a free buffer */
    }

    return pb->freeq[--pb->free_count];
}

static int nuttx_write(audio_playback_t* pb, const void* buf, size_t len)
{
    const uint8_t* src = (const uint8_t*)buf;
    size_t remaining = len;
    int ret;

    while (remaining > 0) {
        struct ap_buffer_s* apb = nuttx_get_free_buffer(pb);
        if (!apb) {
            return pb->stopped ? -ECANCELED : -EIO;
        }

        size_t chunk = remaining;
        if (chunk > pb->buf_bytes) {
            chunk = pb->buf_bytes;
        }

        memcpy(apb->samp, src, chunk);
        apb->nbytes    = (apb_samp_t)chunk;
        apb->curbyte   = 0;

        struct audio_buf_desc_s desc;
        memset(&desc, 0, sizeof(desc));
        desc.numbytes  = chunk;
        desc.u.buffer  = apb;

        ret = ioctl(pb->fd, AUDIOIOC_ENQUEUEBUFFER, (unsigned long)&desc);
        if (ret < 0) {
            syslog(LOG_ERR, "[%s] AUDIOIOC_ENQUEUEBUFFER failed: %d\n", TAG, ret);
            return ret;
        }

        if (!pb->started) {
            ret = ioctl(pb->fd, AUDIOIOC_START, 0);
            if (ret < 0) {
                syslog(LOG_ERR, "[%s] AUDIOIOC_START failed: %d\n", TAG, ret);
                return ret;
            }
            pb->started = 1;
        }

        src += chunk;
        remaining -= chunk;
        pb->total_written += chunk;
    }

    return (int)len;
}
